def read_bytes(path):
    with open(path, "rb") as f:
        b = f.read()
    while b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8")
    if b[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return b.decode("utf-16")
    head = b[:2048].decode("latin-1")
    m = re.search(r"^#\s*charset\s*:\s*([\w.\-]+)", head, re.M | re.I)
    if m:
        try:
            return b.decode(m.group(1))
        except LookupError:
            pass
