def sid(s):
    m = re.search(r"(\d+)", s or "")
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def norm_unit(s):
    s = (s or "").strip().lower()
    m = re.match(r"[a-z]+", s)
    s = m.group(0) if m else ""
    return {"kgs": "kg", "kilogram": "kg", "lbs": "lb", "gram": "g", "grams": "g"}.get(s, s)


def parse_num(s, depot=None):
    s = s.strip().replace(" ", "")
    if depot == "west":
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Fraction(Decimal(s))


def parse_weight(text, unit, depot=None):
    """text may carry its own unit suffix; unit is the fallback."""
    m = re.match(r"^\s*([-+\d.,\s]+?)\s*([A-Za-z]+)?\s*$", text)
    if not m:
        raise ValueError("bad weight %r" % text)
    u = norm_unit(m.group(2)) if m.group(2) else unit
    return parse_num(m.group(1), depot) * FACTORS[u]


def norm_form(f):
    f = (f or "").strip().lower()
    return f.split()[0] if f else f


def parse_date(text, form):
    """Return a datetime (UTC) for a date or timestamp string."""
    t = text.strip()
    if re.match(r"^\d{4}-\d{2}-\d{2}[T ]\d", t):
