    delim = DELIMS[depot]
    cols_known = set(COLUMNS[depot])
    directives = {}
    seq = None
    header = None
    out = []
    for is_comment, line in logical_lines(text, delim == ","):
        if is_comment:
            m = re.match(r"^#\s*([A-Za-z][A-Za-z ]*?)\s*[:=]\s*(.*?)\s*$", line)
            if m:
                name = re.sub(r"\s+", " ", m.group(1).lower())
                directives[name] = m.group(2)
                if name == "seq" and seq is None:
                    seq = int(m.group(2))
            continue
        if delim == ",":
            row = next(csv.reader([line]))
        else:
            row = line.split(delim)
        stripped = [c.strip() for c in row]
        if all(c.lower() in cols_known for c in stripped) and stripped:
            header = [c.lower() for c in stripped]
            continue
        if header is None:
            header = list(COLUMNS[depot])
        if stripped[0].upper() == "TOTAL" and depot == "east":
            continue
        row_unit = None
        if len(row) == len(header) + 1 and norm_unit(row[-1]) in FACTORS:
            row_unit = norm_unit(row[-1])
            row = row[:-1]
        if len(row) != len(header):
            if depot == "harbor" and len(row) == 2:
                row = row + [""] * (len(header) - 2)
            else:
                # trailer / count line or malformed row
                if len(row) < len(header) and len(row) <= 2:
                    continue
                raise ValueError("%s: bad row %r (header %r)" % (depot, row, header))
        r = dict(zip(header, row))
        out.append((r, row_unit, dict(directives)))
    return seq, out


def conv_delimited(depot, rows):
    recs = []
    for r, row_unit, d in rows:
        if depot == "east":
            t, i, ship, w, st = r["type"], r["id"], r["shipped"], r.get("gross", ""), r["status"]
            wunit = d.get("unit")
        elif depot == "harbor":
            t, i, ship, w, st = r["rec"], r["ref"], r.get("date", ""), r.get("weight", ""), r.get("state", "")
            wunit = None
            st = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                  "RET": "returned", "HLD": "held"}.get(st.strip().upper(), st)
        elif depot == "lakeside":
            t, i, ship, w, st = r["kind"], r["id"], r["shipped"], r.get("gross_kg", ""), r["status"]
            wunit = "kg"
        elif depot == "river":
            t, i, ship, w, st = r["t"], r["ref"], r["shipped"], r["weight"], r["status"]
            wunit = d.get("weight unit")
        else:
            t, i, ship, w, st = r["typ"], r["id"], r["shipped"], r["weight"], r["status"]
            wunit = d.get("weight unit")
        typ = TYPES[t.strip().lower()]
        num = sid(i)
        if typ == "void":
            recs.append(Rec(num, typ))
            continue
        unit = row_unit or norm_unit(wunit) or "kg"
        if depot == "lakeside":
            unit = "kg"
        form = d.get("dates") or d.get("date format") or BASE_DATE[depot]
        if depot == "west" and not (d.get("dates") or d.get("date format")):
            form = "dd.mm.yyyy"
        recs.append(Rec(num, typ, parse_date(ship, form), parse_weight(w, unit, depot),
                        norm_status(st)))
    return recs


def parse_xml(path):
    b = read_bytes(path)
    root = ET.fromstring(b)
    seq = int(root.get("seq", 0))
    root_unit = norm_unit(root.get("weight-unit")) or "kg"
    recs = []

    def get(el, name):
        v = el.get(name)
        if v is not None:
            return v
        c = el.find(name)
        return c.text.strip() if c is not None and c.text else None

    for el in root.iter("shipment"):
        typ = TYPES[(get(el, "type") or "").strip().lower()]
        num = sid(el.get("id") or get(el, "id"))
        if typ == "void":
            recs.append(Rec(num, typ))
            continue
        wel = el.find("weight")
        wtext = wel.text if wel is not None and wel.text else el.get("weight")
        unit = norm_unit(wel.get("unit")) if wel is not None and wel.get("unit") else None
        unit = unit or norm_unit(el.get("weight-unit")) or root_unit
        recs.append(Rec(num, typ, parse_date(get(el, "shipped"), "dmy"),
                        parse_weight(wtext, unit), norm_status(get(el, "status"))))
    return seq, recs


def parse_json(text):
    seq = None
    recs = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        for o in (v if isinstance(v, list) else [v]):
            if "meta" in o and "id" not in o:
                if seq is None and "seq" in o["meta"]:
                    seq = int(o["meta"]["seq"])
                continue
            typ = TYPES[str(o.get("kind") or "").strip().lower()]
            num = sid(str(o["id"]))
            if typ == "void":
                recs.append(Rec(num, typ))
                continue
            wk = [k for k in o if k.startswith("weight_")]
            k = wk[0]
            w = o[k]
            recs.append(Rec(num, typ, parse_date(o["shipped_at"], "iso"),
                            parse_weight(str(w), norm_unit(k[7:])), norm_status(o["status"])))
    return seq, recs


FW = {
    # name: (length, type, id, shipped, weight, status, shipped-kind, weight unit, divisor)
    "FW1": dict(n=42, id=(0, 9), type=(9, 10), ship=(10, 17), w=(17, 25), st=(25, 26),
