    "FW2": dict(n=43, id=(1, 10), type=(0, 1), ship=(10, 18), w=(18, 26), st=(26, 27),
                sk="ymd", unit="kg", div=100),
    "FW3": dict(n=41, id=(0, 9), type=(16, 17), ship=(9, 16), w=(17, 24), st=(24, 25),
                sk="ydoy", unit="lb", div=10),
}
