def parse_fixed(text):
    seq = None
    layout = None
    recs = []
    by_len = {v["n"]: k for k, v in FW.items()}
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\f" in line or "SOUTH DEPOT" in line or not line.strip():
            continue
        m = re.match(r"^#SEQ\s+(\d+)", line)
        if m:
            if seq is None:
                seq = int(m.group(1))
            continue
        m = re.match(r"^#LAYOUT\s+(\w+)", line)
        if m:
            layout = m.group(1).upper()
            continue
        if line.startswith("#"):
            continue
        if len(line) in by_len:
            lay = by_len[len(line)]
        elif layout:
            lay = layout
            line = line.ljust(FW[lay]["n"])
        else:
            raise ValueError("fixed line of unknown layout %r" % line)
        L = FW[lay]
        sl = lambda k: line[L[k][0]:L[k][1]]
        typ = TYPES[sl("type").strip().lower()]
        num = sid(sl("id"))
        if typ == "void":
            recs.append(Rec(num, typ))
            continue
        s = sl("ship")
        if L["sk"] == "ydoy":
            when = dt.datetime(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:]) - 1)
        else:
            when = dt.datetime(int(s[:4]), int(s[4:6]), int(s[6:8]))
        kg = Fraction(int(sl("w")), L["div"]) * FACTORS[L["unit"]]
        recs.append(Rec(num, typ, when, kg, SCODES[sl("st").strip().upper()]))
    return seq, recs


def parse_file(depot, path):
    raw = read_bytes(path)
    if depot == "central":
        return parse_xml(path)
    text = decode(raw)
    if depot == "north":
        return parse_json(text)
    if depot == "south":
        return parse_fixed(text)
    seq, rows = parse_delimited(depot, text)
    return seq, conv_delimited(depot, rows)


# --------------------------------------------------------------------- main
def money(fr):
    d = Decimal(fr.numerator) / Decimal(fr.denominator)
    return float(Decimal(fr.numerator * 10**6 // fr.denominator) / 10**6 if False else
                 (Fraction(fr) * 100 + Fraction(1, 2)).__floor__() / Fraction(100)
                 if False else _round2(fr))


def _round2(fr):
    n = (fr * 100 + Fraction(1, 2)).__floor__()
    return float(Decimal(n) / 100)


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-", 1)[0]
        seq, recs = parse_file(depot, p)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                if r.type == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.type == "correction":
                    corrections += 1
                    cur[r.num] = r
                else:
                    corrections += 1
                    cur.pop(r.num, None)
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    owners = {}
    for depot in sorted(current, key=lambda d: (order.get(d, 99), d)):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    depots = {d: [0, Fraction(0)] for d in sorted(exports)}
    months = {}
    for num, ds in owners.items():
        d = ds[0]
        r = current[d][num]
        if not r.counted():
            continue
        depots[d][0] += 1
        depots[d][1] += r.kg
        m = months.setdefault("%04d-%02d" % (r.when.year, r.when.month), [0, Fraction(0)])
        m[0] += 1
        m[1] += r.kg

    result = {
        "depots": {d: {"shipments": v[0], "total_kg": _round2(v[1])} for d, v in depots.items()},
        "months": {k: {"shipments": v[0], "total_kg": _round2(v[1])}
                   for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
