    directives = {}
    seq = None
    header = None
    out = []
    for is_comment, line in logical_lines(text, delim == ","):
        if is_comment:
            m = re.match(r"^#\s*([A-Za-z][A-Za-z ]*?)\s*[:=]\s*(.*?)\s*$", line)
            if m:
                name = re.sub(r"\s+", " ", m.group(1).lower())
                directives[name] = m.group(2)
                if name == "seq" and seq is None:
                    seq = int(m.group(2))
            continue
        if delim == ",":
            row = next(csv.reader([line]))
        else:
            row = line.split(delim)
        stripped = [c.strip() for c in row]
        if all(c.lower() in cols_known for c in stripped) and stripped:
            header = [c.lower() for c in stripped]
            continue
        if header is None:
            header = list(COLUMNS[depot])
        if stripped[0].upper() == "TOTAL" and depot == "east":
            continue
        row_unit = None
        if len(row) == len(header) + 1 and norm_unit(row[-1]) in FACTORS:
            row_unit = norm_unit(row[-1])
            row = row[:-1]
        if len(row) != len(header):
            if depot == "harbor" and len(row) == 2:
                row = row + [""] * (len(header) - 2)
            else:
                # trailer / count line or malformed row
                if len(row) < len(header) and len(row) <= 2:
                    continue
                raise ValueError("%s: bad row %r (header %r)" % (depot, row, header))
        r = dict(zip(header, row))
        out.append((r, row_unit, dict(directives)))
    return seq, out


def conv_delimited(depot, rows):
    recs = []
    for r, row_unit, d in rows:
        if depot == "east":
            t, i, ship, w, st = r["type"], r["id"], r["shipped"], r.get("gross", ""), r["status"]
            wunit = d.get("unit")
        elif depot == "harbor":
            t, i, ship, w, st = r["rec"], r["ref"], r.get("date", ""), r.get("weight", ""), r.get("state", "")
            wunit = None
            st = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                  "RET": "returned", "HLD": "held"}.get(st.strip().upper(), st)
        elif depot == "lakeside":
            t, i, ship, w, st = r["kind"], r["id"], r["shipped"], r.get("gross_kg", ""), r["status"]
            wunit = "kg"
        elif depot == "river":
            t, i, ship, w, st = r["t"], r["ref"], r["shipped"], r["weight"], r["status"]
            wunit = d.get("weight unit")
        else:
            t, i, ship, w, st = r["typ"], r["id"], r["shipped"], r["weight"], r["status"]
            wunit = d.get("weight unit")
        typ = TYPES[t.strip().lower()]
        num = sid(i)
        if typ == "void":
            recs.append(Rec(num, typ))
            continue
        unit = row_unit or norm_unit(wunit) or "kg"
        if depot == "lakeside":
            unit = "kg"
        form = d.get("dates") or d.get("date format") or BASE_DATE[depot]
        if depot == "west" and not (d.get("dates") or d.get("date format")):
            form = "dd.mm.yyyy"
        recs.append(Rec(num, typ, parse_date(ship, form), parse_weight(w, unit, depot),
                        norm_status(st)))
    return recs


def parse_xml(path):
    b = read_bytes(path)
    root = ET.fromstring(b)
    seq = int(root.get("seq", 0))
    root_unit = norm_unit(root.get("weight-unit")) or "kg"
    recs = []

    def get(el, name):
        v = el.get(name)
        if v is not None:
            return v
        c = el.find(name)
        return c.text.strip() if c is not None and c.text else None

    for el in root.iter("shipment"):
        typ = TYPES[(get(el, "type") or "").strip().lower()]
        num = sid(el.get("id") or get(el, "id"))
        if typ == "void":
            recs.append(Rec(num, typ))
            continue
        wel = el.find("weight")
        wtext = wel.text if wel is not None and wel.text else el.get("weight")
        unit = norm_unit(wel.get("unit")) if wel is not None and wel.get("unit") else None
        unit = unit or norm_unit(el.get("weight-unit")) or root_unit
        recs.append(Rec(num, typ, parse_date(get(el, "shipped"), "dmy"),
                        parse_weight(wtext, unit), norm_status(get(el, "status"))))
    return seq, recs


def parse_json(text):
    seq = None
    recs = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        for o in (v if isinstance(v, list) else [v]):
            if "meta" in o and "id" not in o:
                if seq is None and "seq" in o["meta"]:
                    seq = int(o["meta"]["seq"])
                continue
            typ = TYPES[str(o.get("kind") or "").strip().lower()]
            num = sid(str(o["id"]))
            if typ == "void":
                recs.append(Rec(num, typ))
                continue
            wk = [k for k in o if k.startswith("weight_")]
            k = wk[0]
            w = o[k]
            recs.append(Rec(num, typ, parse_date(o["shipped_at"], "iso"),
                            parse_weight(str(w), norm_unit(k[7:])), norm_status(o["status"])))
    return seq, recs


FW = {
    # name: (length, type, id, shipped, weight, status, shipped-kind, weight unit, divisor)
    "FW1": dict(n=42, id=(0, 9), type=(9, 10), ship=(10, 17), w=(17, 25), st=(25, 26),
                sk="ydoy", unit="g", div=1),
    "FW2": dict(n=43, id=(1, 10), type=(0, 1), ship=(10, 18), w=(18, 26), st=(26, 27),
                sk="ymd", unit="kg", div=100),
    "FW3": dict(n=41, id=(0, 9), type=(16, 17), ship=(9, 16), w=(17, 24), st=(24, 25),
                sk="ydoy", unit="lb", div=10),
}
SCODES = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned",
          "H": "held"}


def parse_fixed(text):
    seq = None
    layout = None
    recs = []
    by_len = {v["n"]: k for k, v in FW.items()}
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\f" in line or "SOUTH DEPOT" in line or not line.strip():
            continue
        m = re.match(r"^#SEQ\s+(\d+)", line)
        if m:
            if seq is None:
                seq = int(m.group(1))
            continue
        m = re.match(r"^#LAYOUT\s+(\w+)", line)
        if m:
            layout = m.group(1).upper()
            continue
        if line.startswith("#"):
            continue
        if len(line) in by_len:
            lay = by_len[len(line)]
        elif layout:
            lay = layout
            line = line.ljust(FW[lay]["n"])
        else:
            raise ValueError("fixed line of unknown layout %r" % line)
        L = FW[lay]
        sl = lambda k: line[L[k][0]:L[k][1]]
        typ = TYPES[sl("type").strip().lower()]
        num = sid(sl("id"))
        if typ == "void":
            recs.append(Rec(num, typ))
            continue
        s = sl("ship")
        if L["sk"] == "ydoy":
            when = dt.datetime(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:]) - 1)
        else:
            when = dt.datetime(int(s[:4]), int(s[4:6]), int(s[6:8]))
        kg = Fraction(int(sl("w")), L["div"]) * FACTORS[L["unit"]]
        recs.append(Rec(num, typ, when, kg, SCODES[sl("st").strip().upper()]))
    return seq, recs


def parse_file(depot, path):
    raw = read_bytes(path)
    if depot == "central":
        return parse_xml(path)
    text = decode(raw)
    if depot == "north":
        return parse_json(text)
    if depot == "south":
        return parse_fixed(text)
    seq, rows = parse_delimited(depot, text)
    return seq, conv_delimited(depot, rows)


# --------------------------------------------------------------------- main
def money(fr):
    d = Decimal(fr.numerator) / Decimal(fr.denominator)
    return float(Decimal(fr.numerator * 10**6 // fr.denominator) / 10**6 if False else
                 (Fraction(fr) * 100 + Fraction(1, 2)).__floor__() / Fraction(100)
                 if False else _round2(fr))


def _round2(fr):
    n = (fr * 100 + Fraction(1, 2)).__floor__()
    return float(Decimal(n) / 100)


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-", 1)[0]
        seq, recs = parse_file(depot, p)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                if r.type == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.type == "correction":
                    corrections += 1
                    cur[r.num] = r
                else:
                    corrections += 1
                    cur.pop(r.num, None)
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    owners = {}
    for depot in sorted(current, key=lambda d: (order.get(d, 99), d)):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    depots = {d: [0, Fraction(0)] for d in sorted(exports)}
    months = {}
    for num, ds in owners.items():
        d = ds[0]
        r = current[d][num]
        if not r.counted():
            continue
        depots[d][0] += 1
        depots[d][1] += r.kg
        m = months.setdefault("%04d-%02d" % (r.when.year, r.when.month), [0, Fraction(0)])
        m[0] += 1
        m[1] += r.kg

    result = {
        "depots": {d: {"shipments": v[0], "total_kg": _round2(v[1])} for d, v in depots.items()},
        "months": {k: {"shipments": v[0], "total_kg": _round2(v[1])}
                   for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
